/// Bir Nasreddin Hoca fıkrası: başlık, dört sahne, üç parçalı nükte, iki düz yanıt.
class HocaTale {
  final String id;
  final List<String> title;
  final List<List<String>> panels;
  final List<List<String>> seg;
  final List<List<String>> flats;
  const HocaTale(this.id, this.title, this.panels, this.seg, this.flats);
}

/// Bir Hacivat ile Karagöz sahnesi: altı replik (H, K, H, K, H, K) ve 3. ile 6. replikteki eşyalar.
class KaraScene {
  final String id;
  final List<String> title;
  final List<List<String>> lines;
  final List<int> props;
  const KaraScene(this.id, this.title, this.lines, this.props);
}

